the problem is that these object can't simply be merged, they are immutable and have to have their reference copied, instead of attempting to merge them deeply.

this is my workaround

```ts
  @Column({ type: 'timestamp with time zone', name: 'created_at', update: false, insert: false })
  private readonly _createdAt!: Date;

  @Column({ type: 'timestamp with time zone', name: 'modified_at', insert: false })
  private _modifiedAt!: Date;

  get createdAt(): ZonedDateTime {
    return ZonedDateTime.from(nativeJs(this._createdAt));
  }

  get modifiedAt(): ZonedDateTime {
    return ZonedDateTime.from(nativeJs(this._modifiedAt));
  }

  set modifiedAt(datetime: ZonedDateTime) {
    this._modifiedAt = convert(datetime).toDate();
  }
```
